    // Correct decomposition into 3 non-overlapping tetrahedra covering the full wedge volume (0.5):
    // - Tet 1: N1,N2,N3,N5  -> nodes[0,1,2,4]
    // - Tet 2: N1,N3,N4,N5  -> nodes[0,2,3,4]
    // - Tet 3: N3,N4,N5,N6  -> nodes[2,3,4,5]
    // Sum of volumes = 1/6 + 1/6 + 1/6 = 0.5 → exact.
    std::vector<std::vector<int>> tetrahedrons = {
        {0, 1, 2, 4}, // N1,N2,N3,N5
        {0, 2, 3, 4}, // N1,N3,N4,N5
        {2, 3, 4, 5}  // N3,N4,N5,N6
    };

    // Global stiffness matrix: 6 nodes * 3 DOF = 18x18
    Eigen::MatrixXd K_global = Eigen::MatrixXd::Zero(18, 18);

